#!/usr/bin/env python3
"""surrounding-config-files.py <folder>: ONE CASE A FOLDER: what the FILES AROUND a program decide (.env, bunfig.toml, tsconfig.json, package.json), the loaders, what a module is told, and a few corners of TypeScript's emit that change behavior."""
import os, sys, json
out = sys.argv[1]; cases = {}
def case(name, files): cases[name] = files
TS = lambda o: json.dumps({"compilerOptions": o})
case("dot-env", {".env": "FROM_DOT_ENV=yes\nQUOTED=\"two words\"\nEXPANDED=${FROM_DOT_ENV}-more\n", "main.ts": 'console.log(process.env.FROM_DOT_ENV, Bun.env.FROM_DOT_ENV, import.meta.env.FROM_DOT_ENV, process.env.QUOTED, process.env.EXPANDED, process.env["FROM" + "_DOT_ENV"]);\n'})
case("dot-env-local-and-mode", {".env": "A=base\nB=base\n", ".env.local": "B=local\n", ".env.development": "C=development\n", ".env.production": "C=production\n", "main.ts": 'console.log(process.env.A, process.env.B, process.env.C, process.env.NODE_ENV);\n'})
case("env-file-flag", {".env.other": "OTHER=from the flag\n", "flags.txt": "--env-file=.env.other", "main.ts": 'console.log(process.env.OTHER);\n'})
case("node-env", {"main.ts": 'function mode(): string { return process.env.NODE_ENV === "production" ? "production" : "not production: " + process.env.NODE_ENV; }\nconsole.log(mode()); process.env.NODE_ENV = "production"; console.log(mode()); process.env.NODE_ENV = "test"; console.log(mode()); delete process.env.NODE_ENV; console.log(mode());\n'})
