case("bunfig-define", {"bunfig.toml": '[define]\n"MY_CONSTANT" = "\'defined in bunfig\'"\n"process.env.DEFINED" = "\'yes\'"\n', "main.ts": 'declare const MY_CONSTANT: string;\nconsole.log(typeof MY_CONSTANT === "undefined" ? "not defined" : MY_CONSTANT, process.env.DEFINED);\n'})
case("define-flag", {"flags.txt": "--define MY_CONSTANT='\"by the flag\"'", "main.ts": 'declare const MY_CONSTANT: string;\nconsole.log(typeof MY_CONSTANT === "undefined" ? "not defined" : MY_CONSTANT);\n'})
case("tsconfig-paths", {"tsconfig.json": TS({"paths": {"@/*": ["./src/*"], "lib": ["./src/the-lib.ts"]}}), "src/a.ts": 'export const a: string = "a by a path";\n', "src/the-lib.ts": 'export default "the lib";\n', "main.ts": 'import { a } from "@/a"; import lib from "lib";\nconsole.log(a, lib, (await import("@/a")).a, require("lib").default);\n'})
case("tsconfig-base-url-and-extends", {"base.json": TS({"baseUrl": "./src"}), "tsconfig.json": json.dumps({"extends": "./base.json"}), "src/deep/b.ts": 'export const b: number = 2;\n', "main.ts": 'import { b } from "deep/b";\nconsole.log(b);\n'})
case("package-imports-and-self", {"package.json": json.dumps({"name": "self-pkg", "type": "module", "imports": {"#inner": "./inner.ts", "#cond": {"bun": "./for-bun.ts", "default": "./for-others.ts"}}, "exports": {".": "./entry.ts", "./sub": "./sub.ts"}}), "inner.ts": 'export default "inner";\n', "for-bun.ts": 'export default "for bun";\n', "for-others.ts": 'export default "for others";\n', "entry.ts": 'export default "the entry";\n', "sub.ts": 'export default "the sub";\n', "main.ts": 'import inner from "#inner"; import cond from "#cond"; import self from "self-pkg"; import sub from "self-pkg/sub";\nconsole.log(inner, cond, self, sub);\n'})
for t in ("module", "commonjs"):
    case("package-type-" + t, {"package.json": json.dumps({"type": t}), "lib.js": 'const kind = typeof module !== "undefined" && typeof exports !== "undefined" ? "has module and exports" : "has none";\nglobalThis.said = [kind, typeof require, typeof __filename, (function () { return typeof this; })()].join();\n', "main.ts": 'import "./lib.js";\nconsole.log((globalThis as any).said);\n'})
case("loaders", {"data.json": '{ "a": 1, "list": [1, 2], "default": "d" }', "data.toml": 'title = "toml"\n[t]\nn = 1\n', "note.txt": "text of a file\n", "main.ts": 'import json, { a, list } from "./data.json"; import toml from "./data.toml"; import text from "./note.txt"; import asText from "./data.json" with { type: "text" }; import again from "./data.json" with { type: "json" };\nconsole.log(JSON.stringify(json), a, list.length, JSON.stringify(toml), JSON.stringify(text), (asText as unknown as string).length, again === json, JSON.stringify(require("./data.json")), require("./data.json") === json, JSON.stringify((await import("./data.toml")).default));\njson.a = 5; console.log(a, (await import("./data.json")).default.a);\n'})
case("a-file-import", {"asset.bin": "12345", "main.ts": 'import path from "./asset.bin" with { type: "file" };\nconsole.log(typeof path, path.endsWith("asset.bin"), await Bun.file(path).text());\n'})
case("a-macro", {"macro.ts": 'export function stamp(word: string): string { return word + " at build, in " + typeof Bun; }\nexport function table(): number[] { return [1, 2, 3]; }\n', "main.ts": 'import { stamp, table } from "./macro.ts" with { type: "macro" };\nconsole.log(stamp("made"), table().length);\n'})
case("import-meta", {"sub/lib.ts": 'export const told = [import.meta.main, import.meta.file, import.meta.dir.endsWith("sub"), import.meta.path.endsWith("sub/lib.ts"), import.meta.url.startsWith("file://"), import.meta.dirname === import.meta.dir, import.meta.filename === import.meta.path, typeof import.meta.resolve, import.meta.resolve("./x.ts").endsWith("sub/x.ts"), typeof import.meta.require, typeof import.meta.env, Object.keys(import.meta).sort().join("+")].join();\n', "main.ts": 'import { told } from "./sub/lib.ts";\nconsole.log(import.meta.main, import.meta.file, told); console.log(typeof __dirname, typeof __filename, __filename === import.meta.path, typeof require, typeof this);\n'})
case("what-the-process-says", {"main.ts": 'console.log(Bun.main === import.meta.path, process.argv.length, process.argv[1] === import.meta.path, Bun.argv.length, process.argv0.length > 0, process.execPath === process.argv[0], typeof process.title, process.exitCode, process.stdin.isTTY);\n'})
# TypeScript's emit that changes behavior
BASE = 'class Base { set x(v: number) { console.log("the setter of Base got", v); } get x(): number { return -1; } }\nclass Derived extends Base {\n  // @ts-expect-error TS2610: that is the case\n  x = 5; y!: number; z?: string; declare w: number; }\nconst d = new Derived(); console.log(Object.keys(d).join(), d.x, "y" in d, "z" in d, "w" in d);\n'
case("class-fields-by-default", {"main.ts": BASE})
case("class-fields-defined", {"tsconfig.json": TS({"useDefineForClassFields": True}), "main.ts": BASE})
case("class-fields-assigned", {"tsconfig.json": TS({"useDefineForClassFields": False}), "main.ts": BASE})
case("class-fields-old-target", {"tsconfig.json": TS({"target": "ES2017"}), "main.ts": BASE})
LEGACY = 'const log: string[] = [];\nfunction cls(name: string) { log.push("make class " + name); return (target: Function) => { log.push("class " + name + " " + target.name); }; }\nfunction mem(name: string) { log.push("make member " + name); return (target: any, key: string, desc?: PropertyDescriptor) => { log.push("member " + name + " " + key + " " + typeof desc); }; }\nfunction par(name: string) { return (target: any, key: string | undefined, index: number) => { log.push("parameter " + name + " " + String(key) + " " + index); }; }\nfunction wrap(target: any, key: string, desc: PropertyDescriptor) { const f = desc.value; desc.value = function (this: any, ...a: any[]) { return "wrapped " + f.apply(this, a); }; }\nfunction seal<T extends new (...a: any[]) => object>(C: T) { return class extends C { sealed = true; }; }\n@cls("A") @cls("B") class K { @mem("field") f = 1; @mem("method") @wrap m(@par("p") a: number) { return "m" + a; } @mem("getter") get g() { return 1; } @mem("static") static s() {} constructor(@par("c") c: number) {} }\nconst k: any = new K(1); console.log(log.join(" | ")); console.log(k.m(2), k.f, K.name);\n'
case("legacy-decorators", {"tsconfig.json": TS({"experimentalDecorators": True}), "main.ts": LEGACY})
case("a-legacy-decorator-replaces-the-class", {"tsconfig.json": TS({"experimentalDecorators": True}), "main.ts": 'function seal<T extends new (...a: any[]) => object>(C: T) { return class extends C { sealed = true; }; }\n@seal class K { f = 1; }\nconst k: any = new K(); console.log(k.sealed, k.f);\n'})
case("legacy-decorators-with-metadata", {"tsconfig.json": TS({"experimentalDecorators": True, "emitDecoratorMetadata": True}), "main.ts": 'const seen: string[] = [];\n(Reflect as any).metadata = (key: string, value: any) => (target: any, prop?: string) => { seen.push(key + " " + String(prop) + " " + (Array.isArray(value) ? value.map((v: any) => v?.name).join("+") : value?.name)); };\nfunction d(...a: any[]): void {}\nclass Dep {}\n@d class K { @d f: string = ""; @d n!: number; @d dep!: Dep; @d m(a: number, b: Dep): boolean { return true; } constructor(a: Dep, b: string[]) {} }\nconsole.log(seen.join(" | "));\n'})
case("standard-decorators", {"main.ts": 'const log: string[] = [];\nfunction d(name: string): any { log.push("make " + name); return (value: any, context: any): any => { log.push(name + " " + context.kind + " " + String(context.name) + " " + context.static + " " + context.private); context.addInitializer?.(function (this: any) { log.push("initializer of " + name); }); if (context.kind === "method") return function (this: any, ...a: any[]) { return "wrapped " + value.apply(this, a); }; if (context.kind === "field") return (v: any) => v * 2; }; }\n@d("class") class K { @d("field") f = 21; @d("method") m() { return "m"; } @d("getter") get g() { return 1; } @d("static") static s() { return "s"; } @d("accessor") accessor a = 1; @d("private") #p() { return 1; } }\nconst k = new K(); console.log(log.join(" | ")); console.log(k.f, k.m(), k.a, K.s());\n'})
case("enums-and-namespaces", {"main.ts": 'enum E { A, B = 5, C, D = 1 << 3, S = "s" } enum E { Z = 100 }\nnamespace N { export const a = 1; export function f() { return a + b; } export let b = 2; export namespace Inner { export const c = 3; } } namespace N { export const later = f(); }\nconst enum CE { X = 1, Y = X << 2 }\nconsole.log(JSON.stringify(E), E[5], E.C, JSON.stringify(N), N.f(), N.Inner.c, CE.Y, (() => { N.b = 10; return N.f(); })());\n'})
case("export-equals-and-import-require", {"lib.cts": 'class K { static made = "by export ="; }\nexport = K;\n', "main.ts": 'import K = require("./lib.cts");\nconsole.log(K.made, typeof K);\n'})
case("parameter-properties-and-order", {"main.ts": 'const log: string[] = []; const say = (w: string): string => { log.push(w); return w; };\nclass A { a = say("field a"); constructor(public p: string = say("default p"), readonly q = say("default q")) { say("body"); } b = say("field b"); static s = say("static s"); static { say("static block"); } }\nnew A(); console.log(log.join(" | "), Object.keys(new A("x", "y")).join());\n'})
case("template-objects", {"main.ts": 'const seen: TemplateStringsArray[] = []; function tag(s: TemplateStringsArray, ...v: unknown[]): TemplateStringsArray { seen.push(s); return s; }\nfunction site(n: number) { return tag`a${n}b\\n`; } function other(n: number) { return tag`a${n}b\\n`; }\nconsole.log(site(1) === site(2), site(1) === other(1), Object.isFrozen(site(1)), Object.isFrozen(site(1).raw), site(1).raw[1], site(1)[1].length, Array.isArray(site(1)), tag`\\unicode`[0], [1, 2].map(i => tag`x${i}`).every((s, _, all) => s === all[0]));\n'})
case("names-and-lengths-of-functions", {"main.ts": 'const a = function () {}, b = () => {}, c = class {}, d = { m() {}, get g() { return 1; }, ["k" + 1]: () => {}, f: function () {}, n: function named() {}, async *ag() {} }; let e; e = () => {}; const { f = () => {} } = {} as any; const [g = function () {}] = [] as any[]; function h(a: any, b = 1, ...c: any[]) {} class K { static s() {} #p() {} m = () => {}; static f = function () {}; }\nexport default function () {}\nconsole.log([a, b, c, d.m, Object.getOwnPropertyDescriptor(d, "g")!.get, d.k1, d.f, d.n, d.ag, e, f, g, h, K.s, new K().m, K.f, h.bind(null), (() => {}).bind(null), new Function("a", "b", ""), Symbol.prototype[Symbol.toPrimitive]].map((x: any) => JSON.stringify(x.name) + x.length).join());\n'})
case("text-of-functions", {"main.ts": 'function plain(a: number, b?: string): void { /* kept? */ return; }\nconst arrow = (x: number): number => x * 2; class K<T> { m(v: T): T { return v; } static #p = 1; }\nconsole.log(plain.toString()); console.log(arrow.toString()); console.log(K.toString()); console.log(K.prototype.m.toString()); console.log((function* g() { yield 1; }).toString(), (async () => {}).toString());\n'})
case("stacks", {"lib.ts": 'export function thrower(): never { throw new Error("from lib"); }\nexport class K { m(): string { return new Error("in a method").stack!; } static s(): string { return new Error("in a static").stack!; } get g(): string { return new Error("in a getter").stack!; } }\n', "main.ts": 'import { thrower, K } from "./lib.ts";\nconst clean = (s: string): string => s.split("\\n").map(l => l.replace(/\\(?(file:\\/\\/)?\\/[^ )]*\\//, "(").trim()).join(" < ");\nfunction outer(): void { inner(); } function inner(): void { thrower(); }\ntry { outer(); } catch (e) { console.log(clean((e as Error).stack!)); }\nconsole.log(clean(new K().m())); console.log(clean(K.s())); console.log(clean(new K().g)); console.log(clean([1].map(() => new Error("in a callback").stack!)[0])); await (async () => { await 0; console.log(clean(new Error("behind an await").stack!)); })();\nconst o: any = {}; (Error as any).captureStackTrace(o); console.log(clean(o.stack)); (Error as any).stackTraceLimit = 1; console.log(clean(new Error("limited").stack!));\n'})
case("prepare-stack-trace", {"main.ts": 'function where(): string { const old = (Error as any).prepareStackTrace; (Error as any).prepareStackTrace = (_: unknown, sites: any[]) => sites; const sites: any[] = new Error().stack as any; (Error as any).prepareStackTrace = old; return sites.slice(0, 3).map(s => [s.getFunctionName(), s.getMethodName(), s.getTypeName(), String(s.getFileName()).split(/[\\\\/]/).pop(), s.getLineNumber(), s.getColumnNumber(), s.isNative(), s.isToplevel(), s.isConstructor(), s.isAsync(), s.isEval()].join(":")).join(" | "); }\nclass K { constructor() { console.log(where()); } m() { return where(); } }\nconsole.log(where()); console.log(new K().m());\n'})
case("an-uncaught-error", {"main.ts": 'function f(): void { throw new TypeError("nobody catches this"); }\nconsole.log("before"); f();\n'})
case("an-unhandled-rejection", {"main.ts": 'console.log("before"); Promise.reject(new RangeError("nobody handles this")); setTimeout(() => console.log("never?"), 10);\n'})
case("handlers-of-the-process", {"main.ts": 'process.on("exit", (c: number) => console.log("exit", c)); process.on("beforeExit", (c: number) => console.log("beforeExit", c)); process.on("uncaughtException", (e: Error) => { console.log("caught by the process", e.message); }); process.on("unhandledRejection", (e: any) => console.log("rejection", e.message));\nsetTimeout(() => { throw new Error("thrown in a timer"); }, 1); Promise.reject(new Error("rejected")); process.exitCode = 4;\n'})
for name, files in cases.items():
    for f, text in files.items():
        os.makedirs(os.path.dirname(f"{out}/{name}/{f}"), exist_ok=True); open(f"{out}/{name}/{f}", "w").write(text)
print(len(cases), "cases")
